import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Agent Course (Free) 学习笔记","description":"","frontmatter":{},"headers":[],"relativePath":"tech/patterns/agent/agent-course.md","filePath":"tech/patterns/agent/agent-course.md","lastUpdated":1787046041000}'),o={name:"tech/patterns/agent/agent-course.md"};function s(l,t,i,d,h,g){return r(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="agent-course-free-学习笔记" tabindex="-1">Agent Course (Free) 学习笔记 <a class="header-anchor" href="#agent-course-free-学习笔记" aria-label="Permalink to &quot;Agent Course (Free) 学习笔记&quot;">​</a></h1><blockquote><p>来源: <a href="https://github.com/aishwaryanr/awesome-generative-ai-guide" target="_blank" rel="noreferrer">awesome-generative-ai-guide</a> - Applied LLMs Mastery &amp; Agents 101 学习日期: 2026-04-12</p></blockquote><h2 id="一、agent-核心理论框架" tabindex="-1">一、Agent 核心理论框架 <a class="header-anchor" href="#一、agent-核心理论框架" aria-label="Permalink to &quot;一、Agent 核心理论框架&quot;">​</a></h2><h3 id="agent-三组件模型" tabindex="-1">Agent 三组件模型 <a class="header-anchor" href="#agent-三组件模型" aria-label="Permalink to &quot;Agent 三组件模型&quot;">​</a></h3><p>LLM Agent 基于&quot;大语言模型+工具&quot;构建，核心由三个组件构成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  Agent                   │</span></span>
<span class="line"><span>├─────────────┬──────────────┬────────────┤</span></span>
<span class="line"><span>│   Brain    │  Perception  │   Action   │</span></span>
<span class="line"><span>│ (大脑)     │   (感知)      │   (行动)   │</span></span>
<span class="line"><span>└─────────────┴──────────────┴────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>说明</th></tr></thead><tbody><tr><td><strong>Brain</strong></td><td>中央控制器</td><td>存储信息、处理思考、做出决策</td></tr><tr><td><strong>Perception</strong></td><td>感知模块</td><td>解析外部环境的各种感官输入</td></tr><tr><td><strong>Action</strong></td><td>行动模块</td><td>使用工具执行任务并影响周围环境</td></tr></tbody></table><h3 id="实用四组件模型" tabindex="-1">实用四组件模型 <a class="header-anchor" href="#实用四组件模型" aria-label="Permalink to &quot;实用四组件模型&quot;">​</a></h3><p>更常用的工程化框架：</p><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>示例</th></tr></thead><tbody><tr><td><strong>Agent Core</strong></td><td>核心决策</td><td>目标定义、工具指令、行为模式</td></tr><tr><td><strong>Memory Module</strong></td><td>记忆存储</td><td>短期记忆（当前对话）+ 长期记忆（历史积累）</td></tr><tr><td><strong>Tools</strong></td><td>工具调用</td><td>RAG、代码解释器、搜索 API、天气查询</td></tr><tr><td><strong>Planning Module</strong></td><td>规划模块</td><td>任务分解（Task Decomposition）、反思批判（Reflection）</td></tr></tbody></table><h3 id="memory-检索机制" tabindex="-1">Memory 检索机制 <a class="header-anchor" href="#memory-检索机制" aria-label="Permalink to &quot;Memory 检索机制&quot;">​</a></h3><ul><li><strong>语义相似性</strong>: 基于 embedding 的向量检索</li><li><strong>重要性</strong>: 关键信息加权</li><li><strong>时序性</strong>: 最近交互优先</li><li><strong>应用特定指标</strong>: 领域相关的自定义权重</li></ul><hr><h2 id="二、单-agent-与多-agent" tabindex="-1">二、单 Agent 与多 Agent <a class="header-anchor" href="#二、单-agent-与多-agent" aria-label="Permalink to &quot;二、单 Agent 与多 Agent&quot;">​</a></h2><h3 id="单-agent-局限" tabindex="-1">单 Agent 局限 <a class="header-anchor" href="#单-agent-局限" aria-label="Permalink to &quot;单 Agent 局限&quot;">​</a></h3><p>LLM Agent 通常孤立运行，缺乏：</p><ul><li>与其他 Agent 协作的能力</li><li>从社会交互中学习的能力</li><li>多轮反馈和协作处理复杂场景</li></ul><h3 id="多智能体系统-multi-agent-system-mas" tabindex="-1">多智能体系统 (Multi-Agent System, MAS) <a class="header-anchor" href="#多智能体系统-multi-agent-system-mas" aria-label="Permalink to &quot;多智能体系统 (Multi-Agent System, MAS)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────┐     ┌──────────┐     ┌──────────┐</span></span>
<span class="line"><span>│ Agent A  │ ←→  │ Agent B  │ ←→  │ Agent C  │</span></span>
<span class="line"><span>│ (专业领域) │     │ (协调器)  │     │ (执行器)  │</span></span>
<span class="line"><span>└──────────┘     └──────────┘     └──────────┘</span></span></code></pre></div><p><strong>优势</strong>:</p><ul><li><strong>分工协作</strong>: 专业化 Agent 处理特定任务</li><li><strong>集体决策</strong>: 多角度分析提升质量</li><li><strong>任务分解</strong>: 复杂任务拆解为多个子任务</li></ul><h3 id="多-agent-交互类型" tabindex="-1">多 Agent 交互类型 <a class="header-anchor" href="#多-agent-交互类型" aria-label="Permalink to &quot;多 Agent 交互类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Cooperative（合作）</strong></td><td>Agent 协同追求共同目标</td><td>任务分解流水线</td></tr><tr><td><strong>Adversarial（对抗）</strong></td><td>Agent 通过博弈优化</td><td>代码评审、质量把控</td></tr></tbody></table><hr><h2 id="三、agent-评估基准" tabindex="-1">三、Agent 评估基准 <a class="header-anchor" href="#三、agent-评估基准" aria-label="Permalink to &quot;三、Agent 评估基准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>基准</th><th>用途</th><th>链接</th></tr></thead><tbody><tr><td>AgentBench</td><td>综合评估</td><td><a href="https://github.com/THUDM/AgentBench" target="_blank" rel="noreferrer">THUDM/AgentBench</a></td></tr><tr><td>IGLU</td><td>目标导向对话</td><td><a href="https://arxiv.org/abs/2304.10750" target="_blank" rel="noreferrer">IGLU</a></td></tr><tr><td>ToolBench</td><td>工具调用能力</td><td><a href="https://arxiv.org/abs/2305.16504" target="_blank" rel="noreferrer">ToolBench</a></td></tr><tr><td>ClemBench</td><td>多样化任务</td><td><a href="https://arxiv.org/abs/2305.13455" target="_blank" rel="noreferrer">ClemBench</a></td></tr></tbody></table><hr><h2 id="四、推荐学习路径-5-day-agent-roadmap" tabindex="-1">四、推荐学习路径 (5-Day Agent Roadmap) <a class="header-anchor" href="#四、推荐学习路径-5-day-agent-roadmap" aria-label="Permalink to &quot;四、推荐学习路径 (5-Day Agent Roadmap)&quot;">​</a></h2><h3 id="day-1-2-基础概念" tabindex="-1">Day 1-2: 基础概念 <a class="header-anchor" href="#day-1-2-基础概念" aria-label="Permalink to &quot;Day 1-2: 基础概念&quot;">​</a></h3><ul><li><a href="https://deepchecks.com/glossary/llm-agents/" target="_blank" rel="noreferrer">LLM Agents Glossary - Deepchecks</a></li><li><a href="https://towardsdatascience.com/navigating-the-world-of-llm-agents-a-beginners-guide-3b8d499db7a9" target="_blank" rel="noreferrer">Navigating LLM Agents: A Beginner&#39;s Guide</a></li><li><a href="https://developer.nvidia.com/blog/introduction-to-llm-agents/" target="_blank" rel="noreferrer">Intro to LLM Agents - Nvidia</a></li></ul><h3 id="day-3-4-核心框架" tabindex="-1">Day 3-4: 核心框架 <a class="header-anchor" href="#day-3-4-核心框架" aria-label="Permalink to &quot;Day 3-4: 核心框架&quot;">​</a></h3><ul><li><a href="https://github.com/aishwaryanr/awesome-generative-ai-guide/blob/main/resources/agents_101_guide.md" target="_blank" rel="noreferrer">Agents 101 Guide</a></li><li><a href="https://lilianweng.github.io/posts/2023-06-23-agent/" target="_blank" rel="noreferrer">LLM Powered Autonomous Agents - Lilian Weng</a></li><li><a href="https://www.promptingguide.ai/research/llm-agents" target="_blank" rel="noreferrer">LLM Agents - Prompt Engineering Guide</a></li></ul><h3 id="day-5-实战构建" tabindex="-1">Day 5: 实战构建 <a class="header-anchor" href="#day-5-实战构建" aria-label="Permalink to &quot;Day 5: 实战构建&quot;">​</a></h3><ul><li><a href="https://www.youtube.com/watch?v=WVUITosaG-g" target="_blank" rel="noreferrer">LangChain Agents Tutorial</a></li><li><a href="https://www.deeplearning.ai/short-courses/ai-agents-in-langgraph/" target="_blank" rel="noreferrer">AI Agents in LangGraph - Deeplearning.AI</a></li><li><a href="https://microsoft.github.io/autogen/docs/Use-Cases/agent_chat/" target="_blank" rel="noreferrer">Multi-Agent on Microsoft Autogen</a></li></ul><hr><h2 id="五、实战案例" tabindex="-1">五、实战案例 <a class="header-anchor" href="#五、实战案例" aria-label="Permalink to &quot;五、实战案例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th><th>链接</th></tr></thead><tbody><tr><td>ChemCrow</td><td>化学领域的工具增强 Agent</td><td><a href="https://arxiv.org/abs/2304.05376" target="_blank" rel="noreferrer">Paper</a></td></tr><tr><td>BabyAGI</td><td>轻量级任务驱动的 Agent</td><td><a href="https://github.com/yoheinakajima/babyagi" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td>OS-Copilot</td><td>通用计算机操作 Agent</td><td><a href="https://arxiv.org/abs/2402.07456" target="_blank" rel="noreferrer">Paper</a></td></tr></tbody></table><hr><h2 id="六、与现有文档的关系" tabindex="-1">六、与现有文档的关系 <a class="header-anchor" href="#六、与现有文档的关系" aria-label="Permalink to &quot;六、与现有文档的关系&quot;">​</a></h2><p>本文档补充以下内容：</p><ul><li><strong>理论框架</strong>: Brain/Perception/Action 三组件模型（现有文档侧重 ReAct/Plan-Execute 等工程模式）</li><li><strong>多 Agent 系统</strong>: 合作与对抗交互模式（现有文档尚未覆盖）</li><li><strong>评估基准</strong>: AgentBench 等标准化评估方法</li></ul><p>建议与 <a href="./">Agent 模式索引</a> 配合阅读。</p><hr><h2 id="相关资源" tabindex="-1">相关资源 <a class="header-anchor" href="#相关资源" aria-label="Permalink to &quot;相关资源&quot;">​</a></h2><ul><li><a href="https://github.com/hyp1231/awesome-llm-powered-agent" target="_blank" rel="noreferrer">awesome-llm-powered-agent</a> - Agent 研究汇总</li><li><a href="https://github.com/e2b-dev/awesome-ai-agents" target="_blank" rel="noreferrer">awesome-ai-agents</a> - AI Agent 工具列表</li><li><a href="https://github.com/aishwaryanr/awesome-generative-ai-guide/blob/main/free_courses/Applied_LLMs_Mastery_2024" target="_blank" rel="noreferrer">Applied LLMs Mastery 2024</a> - 完整课程</li></ul>`,45)])])}const A=e(o,[["render",s]]);export{m as __pageData,A as default};
